+                master: pair.master,
+                writer,
+                killer,
+            },
+        ) {
+            let _ = previous.killer.kill();
+        }
+    }
+
+    let id = options.id;
+    std::thread::Builder::new()
+        .name(format!("pty-reader-{id}"))
+        .spawn(move || {
+            let mut buf = [0u8; 16 * 1024];
+            let mut carry: Vec<u8> = Vec::new();
